using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "ResonantBuzzEffect", menuName = "Data/Battle/Effects/Austra/ResonantBuzz Effect")]
public class ResonantBuzzEffect : Effect
{
	[Header("HornetDustEffect")]
	[SerializeField]
	private BattleAction battleAction;

	[SerializeField]
	private int multiplier;

	[SerializeField]
	private OmenLogic omenLogic;

	protected override string GetEffectDescriptionWithAmountReplacedWithX(string localizedDescription, int amount, GameObject effectOwner)
	{
		localizedDescription = ((!LanguagesIndexes.IsCurrentLanguageSimplifiedChinese()) ? Smart.Format(GetLocalizedDescription(), GetNumberToReplaceWithX(), battleAction.GetActionDescription(multiplier).RemoveLastIfDotOrComma()) : Smart.Format(GetLocalizedDescription(), GetNumberToReplaceWithX()));
		localizedDescription = FormattedDescriptionReplacedWithX(localizedDescription);
		return localizedDescription;
	}

	protected override string GetEffectDescriptionWithAmount(int amount, GameObject effectOwner)
	{
		return Smart.Format(GetLocalizedDescription(), amount, battleAction.GetActionDescription(multiplier).RemoveLastIfDotOrComma());
	}

	public void DealPurification(int purificationAmount)
	{
		omenLogic.ActivateOmen(battleAction, purificationAmount * multiplier, null, null);
	}
}
